package com.jh.knowledgeos.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.jh.knowledgeos.domain.*;import com.jh.knowledgeos.mapper.KnowledgeMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class KnowledgeService{private final KnowledgeMapper mapper;private final AiClient ai;private final ObjectMapper om=new ObjectMapper();public KnowledgeService(KnowledgeMapper m,AiClient a){mapper=m;ai=a;}
private String id(String p){return p+UUID.randomUUID().toString().replace("-","");}
@Transactional @SuppressWarnings("unchecked") public Map<String,Object> extract(Map<String,Object> req){Map<String,Object> r=ai.post("/ai/extract",req);Long kb=Long.valueOf(String.valueOf(req.get("knowledgeBaseId")));Object cards=r.get("cards");if(cards instanceof List)for(Object o:(List<Object>)cards){Map<String,Object>x=(Map<String,Object>)o;KnowledgeCard c=new KnowledgeCard();c.setKnowledgeCode(id("K_"));c.setKnowledgeBaseId(kb);c.setType(String.valueOf(x.get("type")));c.setTitle(String.valueOf(x.get("title")));c.setSummary(String.valueOf(x.get("summary")));c.setContent(String.valueOf(x.get("content")));c.setConfidence(Double.valueOf(String.valueOf(x.get("confidence"))));c.setStatus("DRAFT");c.setVersion(1);mapper.insertCard(c);}Object claims=r.get("claims");if(claims instanceof List)for(Object o:(List<Object>)claims){Map<String,Object>x=(Map<String,Object>)o;Claim c=new Claim();c.setClaimCode(id("CLM_"));c.setKnowledgeBaseId(kb);c.setSubject(String.valueOf(x.get("subject")));c.setPredicate(String.valueOf(x.get("predicate")));c.setObjectValue(String.valueOf(x.get("object")));c.setConditionJson("[]");c.setConfidence(Double.valueOf(String.valueOf(x.get("confidence"))));c.setStatus("UNCERTAIN");mapper.insertClaim(c);}return r;}
public Map<String,Object> query(Map<String,Object> req)throws Exception{String qid=id("Q_");req.put("queryId",qid);Map<String,Object> r=ai.post("/ai/query",req);mapper.insertTrace(qid,Long.valueOf(String.valueOf(req.get("knowledgeBaseId"))),String.valueOf(req.get("query")),om.writeValueAsString(r),String.valueOf(r.get("answer")));r.put("queryId",qid);return r;}
public Map<String,Object> adjudicate(Map<String,Object> req){String type=String.valueOf(req.get("objectType"));String code=String.valueOf(req.get("objectCode"));String decision=String.valueOf(req.get("decision"));if("CLAIM".equalsIgnoreCase(type))mapper.updateClaimStatus(code,decision);else mapper.updateCardStatus(code,decision);return req;}
public List<KnowledgeCard> cards(Long kb){return mapper.listCards(kb);}public List<Claim> claims(Long kb){return mapper.listClaims(kb);}public Map<String,Object> trace(String q){return mapper.getTrace(q);} }
